import re
from .epc_section_generic import EpcSectionGeneric, EpcLine
from ..utils.logger import logger


class SectionGnb(EpcSectionGeneric):
    """
    Section "gnb" is a part of epc.lua config file.
    Generated content base on enb.yaml.
    Example generated for CLOUD_MP_CUS_MP:

    exec("set_gnb id=1 type=external plmn=311:489 ng=10.0.1.2 gnb_id=0x01 daemon=:10000 amf=1 plmnList=311:489 nssai=0x1:0xd143a5")
    exec("set_cell id=1 gnb=1 nr_arfcn=633334:633334 gscn=78 eci=0x0000101 pci=0:1 tac=200 nrci=0x01 tdd_cell=on mandatory_for_activation=off")
    exec("set_cell id=2 gnb=1 nr_arfcn=633334:633334 gscn=78 eci=0x0000102 pci=0:2 tac=200 nrci=0x02 tdd_cell=on mandatory_for_activation=off")
    exec("set_cell id=3 gnb=1 nr_arfcn=633334:633334 gscn=78 eci=0x0000103 pci=1:0 tac=200 nrci=0x03 tdd_cell=on mandatory_for_activation=off")
    exec("set_cell id=4 gnb=1 nr_arfcn=633334:633334 gscn=78 eci=0x0000104 pci=1:1 tac=200 nrci=0x04 tdd_cell=on mandatory_for_activation=off")
    exec("set_cell id=5 gnb=1 nr_arfcn=633334:633334 gscn=78 eci=0x0000105 pci=1:2 tac=200 nrci=0x05 tdd_cell=on mandatory_for_activation=off")
    exec("set_cell id=6 gnb=1 nr_arfcn=633334:633334 gscn=78 eci=0x0000106 pci=2:0 tac=200 nrci=0x06 tdd_cell=on mandatory_for_activation=off")
    exec("set_cell id=7 gnb=1 nr_arfcn=633334:633334 gscn=78 eci=0x0000107 pci=2:1 tac=200 nrci=0x07 tdd_cell=on mandatory_for_activation=off")
    exec("set_cell id=8 gnb=1 nr_arfcn=633334:633334 gscn=78 eci=0x0000108 pci=2:2 tac=200 nrci=0x08 tdd_cell=on mandatory_for_activation=off")
    exec("set_cell id=9 gnb=1 nr_arfcn=633334:633334 gscn=78 eci=0x0000109 pci=3:0 tac=200 nrci=0x09 tdd_cell=on mandatory_for_activation=off")
    exec("set_cell id=10 gnb=1 nr_arfcn=633334:633334 gscn=78 eci=0x000010A pci=3:1 tac=200 nrci=0x0a tdd_cell=on mandatory_for_activation=off")
    exec("set_cell id=11 gnb=1 nr_arfcn=633334:633334 gscn=78 eci=0x000010B pci=3:2 tac=200 nrci=0x0b tdd_cell=on mandatory_for_activation=off")
    exec("set_cell id=12 gnb=1 nr_arfcn=633334:633334 gscn=78 eci=0x000010C pci=4:0 tac=200 nrci=0x0c tdd_cell=on mandatory_for_activation=off")
    """

    def _prepare_section_content(self, enb_config, epc_config, *args, **kwargs):
        gnb_keys = []
        for gnb_key in filter(self._filter_gnb, sorted(enb_config.keys())):
            gnb_keys.append(gnb_key)
        if not gnb_keys:
            return

        logger.debug("Generating GNB section")
        for gnb_key in gnb_keys:
            gnb_ent_config = enb_config[gnb_key]
            gnb_id = gnb_ent_config['id']
            gnb_num = gnb_ent_config['num']
            gnb_ip = epc_config.get('amf1', {}).get('ngc_ip_addr')
            if not gnb_ip:
                gnb_ip = '10.0.1.' + str(2 * (int(gnb_id)))
            mcc = gnb_ent_config['mcc']
            mnc = gnb_ent_config['mnc']
            sst = gnb_ent_config['sst']
            sd = gnb_ent_config['sd']
            # gnb_id_macro = f'0x{format(int(gnb_id), "05X")}'
            nssai = f"0x{format(int(sst), 'x')}:0x{format(int(sd), 'x')}"

            # set_gnb id=1 type=external plmn=311:489 s1u=$GNB_S1U_ADDR x2=$GNB_X2_ADDR:36422 ng=$GNB_NG_ADDR gnb_id=0x01
            #   daemon=$SERVER_IP:$DAEMON_PORT x2_peers=none amf=1 plmnList=311:489 nssai=0x1:0xd143a5
            # set_gnb id=1 type=external plmn=311:489 ng=$GNB_NG_ADDR gnb_id=0x01 daemon=$SERVER_IP:$DAEMON_PORT x2_peers=none amf=1 plmnList=311:489
            #   nssai=0x1:0xd143a5
            # set_cell id=1 gnb=1 nr_arfcn=636666:636666 gscn=7880 eci=0x000021f pci=16:2 tac=200 nrci=0x01 tdd_cell=on mandatory_for_activation=off
            gnb_line = f"set_gnb id={gnb_num} type=external plmn={mcc}:{mnc} ng={gnb_ip} " \
                       f"gnb_id=0x{format(int(gnb_id), '02X')} daemon=:{self.EDAEMON_PORT} amf=1 plmnList={mcc}:{mnc} nssai={nssai}"
            subsection_content = [EpcLine(line=gnb_line, exec=True, tab_count=0)]
            for cell_id in sorted(enb_config[gnb_key]['cells'].keys(), key=int):
                cell = enb_config[gnb_key]['cells'][cell_id]
                tac = cell['tac']
                eci = f'0x{format(256 * int(gnb_id) + int(cell_id), "07X")}'
                pci = f"{(int(cell['pci']) // 3)}:{(int(cell['pci']) % 3)}"
                arfcn = cell.get('earfcn')
                if arfcn:
                    arfcn_ul = arfcn
                    arfcn_dl = arfcn
                    tdd_cell_mode = 'on'
                else:
                    arfcn_ul = cell['earfcn_ul']
                    arfcn_dl = cell['earfcn_dl']
                    tdd_cell_mode = 'off'
                freq_band = cell['freq_band']

                cell_line = f"set_cell id={cell_id} gnb={gnb_num} nr_arfcn={arfcn_ul}:{arfcn_dl} gscn={freq_band} eci={eci} pci={pci} tac={tac} "\
                            f"nrci=0x{format(int(cell_id), '02x')} tdd_cell={tdd_cell_mode} mandatory_for_activation=off"
                subsection_content.append(EpcLine(line=cell_line, exec=True, tab_count=0))

            self._section_content.append(subsection_content)

    @staticmethod
    def _filter_gnb(s: str):
        return re.match(r'gnb\d+|vcu\d+', s) is not None
